const fn = new Function(code + "\nreturn { focusPlan };");
const { focusPlan } = fn();
const f = { focusables: 3, currentIndex: 0, forward: true, restoreIndex: 9 };
if (focusPlan(f).next !== 1) throw new Error("Tab from 0 goes to 1.");
if (focusPlan({ ...f, currentIndex: 2 }).next !== 0) throw new Error("Tab from the last wraps to 0.");
if (focusPlan({ ...f, forward: false, currentIndex: 0 }).next !== 2) throw new Error("Shift+Tab from 0 wraps to the last.");

